"use client";

import Image from "next/image";
import { useRouter, useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";
import { Info, KeyRound, LifeBuoy, LogOut, Plus, Store, User } from "lucide-react";
import { DUENO } from "@/lib/datos-demo";
import { pantallaDeEntrada } from "@/lib/navegacion";
import { hayNube } from "@/lib/supabase";
import type { Rubro } from "@/lib/tipos";
import { entrarConCodigo, recuperarPin } from "@/store/cifrado";
import { useCuenta } from "@/store/cuenta";
import { useConexionRed } from "@/store/conexion";
import { useSesion } from "@/store/comercio";
import { useDatos } from "@/store/datos";
import { traerDatosConLlave, useConexion } from "@/store/nube";
import { Conectando, SinConexion, useDatosListos } from "./layout/Marco";
import { RUBROS } from "./layout/Topbar";
import { ActivarCifrado } from "./seguridad/ActivarCifrado";
import { Boton, Campo, claseInput, Segmentado } from "./ui/base";

const INTENTOS_MAXIMOS = 3; // PIN mal escrito 3 veces seguidas...
const ESPERA_SEGUNDOS = 30; // ...y hay que esperar 30 segundos para probar de nuevo

// Pantalla para entrar, en dos pasos:
// 1. Con la nube (Supabase): el dueño abre su cuenta con Gmail UNA vez en la compu del local.
//    Sin las variables de Supabase (o con "Probar la demo") se saltea y quedan los datos de prueba.
//    Con la API configurada, desde ahí se trabaja con los datos de la nube (si no, con la demo).
// 2. Cada turno: elegir el comercio y entrar como empleado (con su nombre) o como jefe (con PIN).
//    En la nube, la primera vez el dueño crea su primer comercio y elige su PIN de jefe.
//    El jefe también puede crear otro comercio desde acá ("+ Crear un comercio nuevo"), con su PIN.
// 3. Cifrado (en la nube): la primera vez que el jefe entra, activa el cifrado anotando su código de recuperación.
//    Después, el empleado entra con su nombre y el código de empleados del comercio, y "Me olvidé el PIN" usa el
//    código de recuperación. Hasta que no se pone el PIN o el código, la API no manda los datos del negocio (están
//    cifrados): al entrar se vuelven a pedir, ya con la llave.
export function Ingreso() {
  const listos = useDatosListos();
  const conexion = useConexion(listos);
  const router = useRouter();
  const { sesion, ingresar, comercioId: ultimoComercio } = useSesion();
  const comercios = useDatos((s) => s.comercios);
  const empleados = useDatos((s) => s.empleados);
  const pinCorrecto = useDatos((s) => s.pinCorrecto);
  const cambiarPin = useDatos((s) => s.cambiarPin);
  const crearComercio = useDatos((s) => s.crearComercio);
  const enNube = useDatos((s) => s.modo === "nube");
  const pinCambiado = useDatos((s) => (s.modo === "nube" ? s.pinConfigurado : s.pin !== null));
  const cifrado = useDatos((s) => s.modo === "nube" && s.cifradoActivo);
  const codigos = useDatos((s) => s.codigos);

  const [comercioId, setComercioId] = useState<number | null>(null);
  const [creando, setCreando] = useState(false); // eligió "+ Crear un comercio nuevo" (solo el jefe, con PIN)
  const [nuevo, setNuevo] = useState<ComercioNuevo>(COMERCIO_VACIO);
  const [quien, setQuien] = useState<"empleado" | "jefe">("empleado");
  const [nombre, setNombre] = useState("");
  const [pin, setPin] = useState("");
  const [pinRepetido, setPinRepetido] = useState(""); // en la nube, la primera vez se elige el PIN
  const [enviando, setEnviando] = useState(false);
  const [error, setError] = useState("");
  const [intentos, setIntentos] = useState(0);
  const [restante, setRestante] = useState(0); // segundos que faltan para poder probar de nuevo
  const [olvido, setOlvido] = useState(false);
  const [codigo, setCodigo] = useState(""); // con el cifrado: el código de empleados del comercio
  const [activando, setActivando] = useState(""); // el PIN de jefe ya comprobado, mientras se activa el cifrado
  const [recupero, setRecupero] = useState({ frase: "", nuevo: "", repetido: "" });
  const reiniciar = useDatos((s) => s.reiniciar);
  const { cuenta, error: errorCuenta, ingresarConGoogle, salirDeLaCuenta } = useCuenta();
  // Con ventas cobradas sin internet todavía sin mandar, se avisa antes (no se borran: se mandan al volver a entrar)
  const cerrarCuenta = () => {
    const { pendientes } = useConexionRed.getState();
    const aviso = `Hay ${pendientes === 1 ? "1 venta" : `${pendientes} ventas`} cobradas sin internet que todavía no se mandaron. ` +
      "Si cerrás la cuenta, quedan guardadas en esta compu y se mandan cuando vuelvas a entrar con esta misma cuenta. ¿Cerrar igual?";
    if (pendientes > 0 && !window.confirm(aviso)) return;
    void salirDeLaCuenta();
  };
  const [probarDemo, setProbarDemo] = useState(false);
  // Los botones "Probar Demo Gratis" de la landing traen ?demo: van directo a la demo, sin pedir Gmail.
  const pideDemo = useSearchParams().has("demo");
  const [yendoAGoogle, setYendoAGoogle] = useState(false);

  useEffect(() => {
    // Se lee la sesión recién (la conexión pudo cerrarla en este mismo momento por ser de la demo)
    const actual = useSesion.getState().sesion;
    if (listos && !conexion.esperando && sesion && actual) router.replace(pantallaDeEntrada(actual.rol === "jefe", comercios.find((c) => c.id === actual.comercioId)));
  }, [listos, conexion.esperando, sesion, router, comercios]);

  // Mientras está bloqueado, la cuenta regresiva baja de a un segundo
  useEffect(() => {
    if (restante <= 0) return;
    const t = setTimeout(() => setRestante((r) => r - 1), 1000);
    return () => clearTimeout(t);
  }, [restante]);

  if (conexion.esperando) return <Conectando />;
  if (!listos) return <div className="min-h-full bg-fondo" aria-busy />;
  if (conexion.estado === "error") {
    return (
      <div className="flex min-h-full flex-col bg-fondo">
        <SinConexion error={conexion.error} reintentar={() => void conexion.reintentar()} />
        <button type="button" onClick={cerrarCuenta} className="mx-auto mb-10 flex items-center gap-1 text-sm text-texto-suave hover:text-texto">
          <LogOut className="size-4" /> Cerrar la cuenta y usar la demo
        </button>
      </div>
    );
  }

  const logo = (
    <div className="mb-8 flex justify-center">
      <Image src="/logo-claro.png" alt="Mantenete" width={240} height={61} className="h-12 w-auto dark:hidden" priority />
      <Image src="/logo-oscuro.png" alt="Mantenete" width={240} height={58} className="hidden h-12 w-auto dark:block" priority />
    </div>
  );

  // Paso 1: todavía no se abrió la cuenta del dueño en esta compu
  if (hayNube && !cuenta && !probarDemo && !pideDemo) {
    return (
      <main className="flex min-h-full items-center justify-center bg-fondo px-4 py-10">
        <div className="w-full max-w-md">
          {logo}
          <div className="flex flex-col gap-5 rounded-xl border border-borde bg-superficie p-6 shadow-sm shadow-black/[0.03] sm:p-8">
            <div>
              <h1 className="text-xl font-semibold tracking-tight">Ingresar</h1>
              <p className="mt-1 text-sm text-texto-suave">
                Entrá con el Gmail con el que contrataste Mantenete. Se hace una sola vez en cada compu o celular del local.
              </p>
            </div>
            {errorCuenta && <p className="rounded-md border border-peligro/40 p-3 text-sm text-peligro">{errorCuenta}</p>}
            <Boton
              variante="primario"
              className="h-11"
              disabled={yendoAGoogle}
              onClick={async () => {
                setYendoAGoogle(true);
                await ingresarConGoogle();
                setYendoAGoogle(false);
              }}
            >
              <LogoGoogle />
              {yendoAGoogle ? "Abriendo Google…" : "Ingresar con Google"}
            </Boton>
            <button type="button" onClick={() => setProbarDemo(true)} className="text-sm text-texto-suave underline underline-offset-2 hover:text-texto">
              Probar la demo sin cuenta
            </button>
          </div>
        </div>
      </main>
    );
  }

  const barraCuenta = cuenta && (
    <p className="mb-3 flex items-center justify-between gap-3 rounded-md border border-borde bg-superficie px-3 py-2 text-sm">
      <span className="min-w-0 truncate">
        Cuenta: <b>{cuenta.nombre || cuenta.email}</b>
        {cuenta.nombre && <span className="text-texto-suave"> · {cuenta.email}</span>}
      </span>
      <button type="button" onClick={cerrarCuenta} className="flex shrink-0 items-center gap-1 text-texto-suave hover:text-texto">
        <LogOut className="size-4" /> Cerrar cuenta
      </button>
    </p>
  );

  // Cuenta nueva en la nube: todavía no tiene comercios, así que primero se crea el primero
  if (enNube && !comercios.length) {
    return (
      <main className="flex min-h-full items-center justify-center bg-fondo px-4 py-10">
        <div className="w-full max-w-md">
          {logo}
          {barraCuenta}
          <PrimerComercio />
        </div>
      </main>
    );
  }

  const elegido = comercioId ?? (comercios.some((c) => c.id === ultimoComercio) ? ultimoComercio : comercios[0]?.id);
  const bloqueado = restante > 0;
  const deEste = empleados.filter((e) => e.comercioId === elegido && e.activo);
  const nombreJefe = enNube ? cuenta?.nombre || "Jefe" : DUENO.nombre;
  // Con el cifrado, si Nahuel borró el PIN desde Supabase, el PIN nuevo se elige con el código de recuperación
  const sinPinConCifrado = enNube && cifrado && !pinCambiado;
  const eligePin = enNube && !pinCambiado && !cifrado; // en la nube no hay PIN de demo: la primera vez se elige
  const recuperando = quien === "jefe" && enNube && cifrado && (olvido || sinPinConCifrado);
  // En la nube el empleado entra con el código del comercio: sin cifrado activado o sin código elegido, todavía no puede
  const sinCodigo = quien === "empleado" && enNube && (!cifrado || !codigos[elegido]);
  const porQueNoEntra = !cifrado
    ? "Primero tiene que entrar el jefe con su PIN: la primera vez protege los datos del negocio. Después elige el código de empleados en Mis comercios."
    : "El jefe todavía no eligió el código de empleados de este comercio. Pedile que entre como jefe y lo elija en Mis comercios.";

  /** Con el PIN bien (o recién elegido): si eligió crear un comercio se crea, y se entra directo. */
  async function entrarComoJefe() {
    const id = creando ? await crearComercio({ ...nuevo, nombre: nuevo.nombre.trim(), direccion: nuevo.direccion.trim() }) : elegido;
    if (enNube) await traerDatosConLlave(); // con la llave del jefe, la API ya abre los datos de todos sus comercios
    ingresar({ rol: "jefe", nombre: nombreJefe, comercioId: id, enNube });
  }

  /** PIN o código mal escrito: cuenta el intento y, al tercero, hay que esperar. */
  function fallo(que: "PIN" | "código") {
    const nuevos = intentos + 1;
    setIntentos(nuevos);
    setPin("");
    setCodigo("");
    if (nuevos >= INTENTOS_MAXIMOS) {
      setIntentos(0);
      setRestante(ESPERA_SEGUNDOS);
      return setError(`Escribiste mal el ${que} ${INTENTOS_MAXIMOS} veces. Esperá ${ESPERA_SEGUNDOS} segundos y probá de nuevo.`);
    }
    return setError(`${que === "PIN" ? "PIN incorrecto" : "Código incorrecto"}. Te quedan ${INTENTOS_MAXIMOS - nuevos} intentos.`);
  }

  async function entrar(e: React.FormEvent) {
    e.preventDefault();
    setError("");
    if (quien === "empleado") {
      if (!nombre.trim()) return setError("Escribí tu nombre: queda anotado en la caja que abras.");
      if (sinCodigo) return setError(porQueNoEntra);
      if (enNube) {
        if (bloqueado || enviando) return;
        setEnviando(true);
        try {
          if (!(await entrarConCodigo(elegido, codigo))) return fallo("código");
          await traerDatosConLlave(); // con la llave del empleado, la API abre los datos de SU comercio
        } catch (err) {
          setCodigo("");
          return setError((err as Error).message);
        } finally {
          setEnviando(false);
        }
      }
      ingresar({ rol: "empleado", nombre: nombre.trim(), comercioId: elegido, enNube });
      return;
    }
    if (bloqueado || enviando) return;
    // Primero se revisa el nombre, así un olvido no gasta un intento de PIN
    if (creando && !nuevo.nombre.trim()) return setError("Escribí el nombre del comercio nuevo.");
    setEnviando(true);
    try {
      let correcto = true;
      if (eligePin) await cambiarPin("", pin, pinRepetido);
      else correcto = await pinCorrecto(pin);
      if (!correcto) return fallo("PIN");
      // En la nube, la primera vez que entra el jefe se activa el cifrado (con el código de recuperación)
      if (enNube && !cifrado) return setActivando(pin);
      await entrarComoJefe();
    } catch (err) {
      // Sin conexión, PIN nuevo que no cumple las reglas, o demasiados intentos (la API traba un minuto)
      setPin("");
      setPinRepetido("");
      setError((err as Error).message);
    } finally {
      setEnviando(false);
    }
  }

  /** "Me olvidé el PIN" con el cifrado: con el código de recuperación se elige un PIN nuevo y se entra. */
  async function recuperar() {
    setError("");
    if (creando && !nuevo.nombre.trim()) return setError("Escribí el nombre del comercio nuevo.");
    setEnviando(true);
    try {
      await recuperarPin(recupero.frase, recupero.nuevo, recupero.repetido);
      setRecupero({ frase: "", nuevo: "", repetido: "" });
      setOlvido(false);
      await entrarComoJefe();
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setEnviando(false);
    }
  }

  if (activando) {
    return (
      <main className="flex min-h-full items-center justify-center bg-fondo px-4 py-10">
        <div className="w-full max-w-md">
          {logo}
          {barraCuenta}
          <div className="rounded-xl border border-borde bg-superficie p-6 shadow-sm shadow-black/[0.03] sm:p-8">
            <ActivarCifrado
              pin={activando}
              alTerminar={entrarComoJefe}
              cancelar={() => {
                setActivando("");
                setPin("");
              }}
            />
          </div>
        </div>
      </main>
    );
  }

  return (
    <main className="flex min-h-full items-center justify-center bg-fondo px-4 py-10">
      <div className="w-full max-w-md">
        {logo}

        {barraCuenta}

        <form onSubmit={entrar} className="flex flex-col gap-5 rounded-xl border border-borde bg-superficie p-6 shadow-sm shadow-black/[0.03] sm:p-8">
          <div>
            <h1 className="text-xl font-semibold tracking-tight">Ingresar</h1>
            <p className="mt-1 text-sm text-texto-suave">
              {cuenta ? "Elegí el comercio y quién atiende este turno." : "Cuando el sistema esté en la nube, acá vas a entrar con tu Gmail."}
            </p>
          </div>

          {!enNube && (
            <p className="flex gap-2.5 rounded-md border border-borde bg-superficie-suave p-3 text-sm">
              <Info className="mt-0.5 size-4 shrink-0 text-texto-suave" />
              <span>
                Demo con datos de prueba. Entrá como jefe con el PIN{" "}
                {pinCambiado ? "que elegiste en Configuración" : <b>{DUENO.pinDemo}</b>}, o como empleado con cualquier nombre.
              </span>
            </p>
          )}

          <Campo etiqueta="Comercio">
            <select
              id="comercio"
              value={creando ? "nuevo" : elegido}
              onChange={(e) => {
                setError("");
                if (e.target.value === "nuevo") {
                  setCreando(true);
                  setQuien("jefe"); // los comercios los crea solo el jefe
                  return;
                }
                setCreando(false);
                setComercioId(Number(e.target.value));
              }}
              className={claseInput}
            >
              {comercios.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.nombre}
                </option>
              ))}
              <option value="nuevo">+ Crear un comercio nuevo</option>
            </select>
          </Campo>

          {creando && (
            <div className="flex flex-col gap-4 rounded-md border border-borde p-4">
              <p className="flex items-center gap-2 text-sm font-medium">
                <Plus className="size-4 text-primary" /> Comercio nuevo (solo el jefe, con su PIN)
              </p>
              <CamposComercio nuevo={nuevo} cambiar={setNuevo} prefijo="nuevo-comercio" />
              <button
                type="button"
                onClick={() => {
                  setCreando(false);
                  setError("");
                }}
                className="self-start text-sm text-texto-suave underline underline-offset-2 hover:text-texto"
              >
                Cancelar y elegir un comercio que ya tengo
              </button>
            </div>
          )}

          <div className={creando ? "hidden" : "flex flex-col gap-1.5"}>
            <span className="text-sm font-medium">¿Quién sos?</span>
            <Segmentado
              etiqueta="¿Quién sos?"
              valor={quien}
              alCambiar={(v) => {
                setQuien(v);
                setError("");
              }}
              opciones={[
                { valor: "empleado", texto: "Empleado" },
                { valor: "jefe", texto: "Jefe" },
              ]}
            />
          </div>

          {quien === "empleado" ? (
            <>
              <Campo etiqueta="Tu nombre" ayuda={deEste.length ? `Empleados de este comercio: ${deEste.map((e) => e.nombre).join(", ")}` : undefined}>
                <input id="nombre" value={nombre} onChange={(e) => setNombre(e.target.value)} placeholder="Ej.: Juan" className={claseInput} autoComplete="off" />
              </Campo>
              {sinCodigo ? (
                <p className="flex gap-2.5 rounded-md border border-borde bg-superficie-suave p-3 text-sm">
                  <Info className="mt-0.5 size-4 shrink-0 text-texto-suave" />
                  <span>{porQueNoEntra}</span>
                </p>
              ) : (
                enNube && (
                  <Campo etiqueta="Código de empleados" ayuda="Los 6 números que te pasó el jefe.">
                    <input
                      id="codigo"
                      type="password"
                      inputMode="numeric"
                      maxLength={6}
                      autoComplete="off"
                      value={codigo}
                      onChange={(e) => setCodigo(e.target.value.replace(/\D/g, ""))}
                      disabled={bloqueado}
                      className={`${claseInput} tracking-[0.4em]`}
                    />
                  </Campo>
                )
              )}
            </>
          ) : recuperando ? (
            <div className="flex flex-col gap-4 rounded-md border border-borde p-4">
              <p className="flex items-center gap-2 text-sm font-medium">
                <LifeBuoy className="size-4 text-primary" /> {sinPinConCifrado ? "Tu PIN se borró: elegí uno nuevo con tu código de recuperación" : "Me olvidé el PIN"}
              </p>
              <p className="text-sm text-texto-suave">Escribí el código de recuperación que anotaste en papel y elegí un PIN nuevo. Tus datos siguen todos.</p>
              <Campo etiqueta="Código de recuperación" ayuda="Las 24 letras y números, con o sin guiones.">
                <input
                  id="frase-recuperar"
                  value={recupero.frase}
                  onChange={(e) => setRecupero({ ...recupero, frase: e.target.value })}
                  autoComplete="off"
                  autoCapitalize="characters"
                  spellCheck={false}
                  translate="no"
                  className={`${claseInput} notranslate font-mono uppercase tracking-wider`}
                />
              </Campo>
              <div className="grid grid-cols-2 gap-3">
                <Campo etiqueta="PIN nuevo">
                  <input id="pin-nuevo-recuperar" type="password" inputMode="numeric" maxLength={8} autoComplete="off" value={recupero.nuevo} onChange={(e) => setRecupero({ ...recupero, nuevo: e.target.value.replace(/\D/g, "") })} className={`${claseInput} tracking-[0.4em]`} />
                </Campo>
                <Campo etiqueta="Repetilo">
                  <input id="pin-repetido-recuperar" type="password" inputMode="numeric" maxLength={8} autoComplete="off" value={recupero.repetido} onChange={(e) => setRecupero({ ...recupero, repetido: e.target.value.replace(/\D/g, "") })} className={`${claseInput} tracking-[0.4em]`} />
                </Campo>
              </div>
              <div className="flex flex-wrap justify-between gap-2">
                {!sinPinConCifrado && (
                  <Boton variante="fantasma" onClick={() => setOlvido(false)}>
                    Volver a poner mi PIN
                  </Boton>
                )}
                <Boton variante="primario" icono={KeyRound} disabled={enviando} onClick={() => void recuperar()} className="ml-auto">
                  {enviando ? "Comprobando…" : "Guardar PIN nuevo y entrar"}
                </Boton>
              </div>
            </div>
          ) : eligePin ? (
            <>
              <p className="text-sm text-texto-suave">
                Es la primera vez: elegí tu PIN de jefe (de 4 a 8 números). Lo vas a usar para entrar como jefe en cualquier compu del local; los empleados entran con su nombre.
              </p>
              <div className="grid grid-cols-2 gap-3">
                <Campo etiqueta="PIN nuevo">
                  <input id="pin" type="password" inputMode="numeric" maxLength={8} autoComplete="off" value={pin} onChange={(e) => setPin(e.target.value.replace(/\D/g, ""))} className={`${claseInput} tracking-[0.4em]`} autoFocus />
                </Campo>
                <Campo etiqueta="Repetilo">
                  <input id="pin-repetido" type="password" inputMode="numeric" maxLength={8} autoComplete="off" value={pinRepetido} onChange={(e) => setPinRepetido(e.target.value.replace(/\D/g, ""))} className={`${claseInput} tracking-[0.4em]`} />
                </Campo>
              </div>
            </>
          ) : (
            <Campo etiqueta={enNube ? "PIN de jefe" : `PIN de jefe (${DUENO.nombre})`}>
              <input
                id="pin"
                type="password"
                inputMode="numeric"
                maxLength={8}
                value={pin}
                onChange={(e) => setPin(e.target.value.replace(/\D/g, ""))}
                disabled={bloqueado}
                className={`${claseInput} tracking-[0.4em]`}
                autoFocus
              />
            </Campo>
          )}

          {error && <p className="text-sm text-peligro">{bloqueado ? `${error} (${restante} s)` : error}</p>}

          {/* Olvidé mi PIN: en la demo no hay mail para recuperarlo, así que se vuelve a empezar (con Supabase va por mail) */}
          {quien === "jefe" && pinCambiado && !recuperando && (
            <div className="text-sm text-texto-suave">
              {olvido && enNube ? (
                <p className="flex flex-col gap-2 rounded-md border border-borde p-3">
                  Escribinos a Mantenete desde el Gmail de tu cuenta y te borramos el PIN. Después, al entrar como jefe, elegís uno nuevo.
                  <Boton variante="fantasma" className="self-start" onClick={() => setOlvido(false)}>Entendido</Boton>
                </p>
              ) : olvido ? (
                <p className="flex flex-col gap-2 rounded-md border border-borde p-3">
                  En la demo, para recuperar el PIN hay que volver a empezar: se borran tus cambios y vuelve el PIN {DUENO.pinDemo}.
                  <span className="flex gap-2">
                    <Boton variante="fantasma" onClick={() => setOlvido(false)}>Cancelar</Boton>
                    <Boton
                      variante="peligro"
                      onClick={() => {
                        reiniciar();
                        setOlvido(false);
                        setError("");
                      }}
                    >
                      Volver a empezar
                    </Boton>
                  </span>
                </p>
              ) : (
                <button type="button" onClick={() => setOlvido(true)} className="underline underline-offset-2 hover:text-texto">
                  Me olvidé el PIN
                </button>
              )}
            </div>
          )}

          {!recuperando && (
            <Boton type="submit" variante="primario" icono={quien === "jefe" ? KeyRound : User} disabled={sinCodigo || ((quien === "jefe" || enNube) && (bloqueado || enviando))} className="h-11">
              {enviando ? "Comprobando…" : creando ? "Crear comercio y entrar" : eligePin && quien === "jefe" ? "Guardar PIN y entrar" : "Entrar"}
            </Boton>
          )}
        </form>
      </div>
    </main>
  );
}

type ComercioNuevo = { nombre: string; rubro: Rubro; direccion: string; usaTicket: boolean };
const COMERCIO_VACIO: ComercioNuevo = { nombre: "", rubro: "kiosco", direccion: "", usaTicket: true };

/** Los datos de un comercio nuevo (el primero de la cuenta, o uno más desde el ingreso). */
function CamposComercio({ nuevo, cambiar, prefijo }: { nuevo: ComercioNuevo; cambiar: (c: ComercioNuevo) => void; prefijo: string }) {
  return (
    <>
      <Campo etiqueta="Nombre del comercio">
        <input id={prefijo === "primer" ? "primer-comercio" : `${prefijo}-nombre`} value={nuevo.nombre} onChange={(e) => cambiar({ ...nuevo, nombre: e.target.value })} placeholder="Ej.: Kiosco El Paso" className={claseInput} required autoFocus />
      </Campo>
      <Campo etiqueta="Rubro">
        <select id={`${prefijo}-rubro`} value={nuevo.rubro} onChange={(e) => cambiar({ ...nuevo, rubro: e.target.value as Rubro })} className={claseInput}>
          {(Object.keys(RUBROS) as Rubro[]).map((r) => (
            <option key={r} value={r}>
              {RUBROS[r]}
            </option>
          ))}
        </select>
      </Campo>
      <Campo etiqueta="Dirección (opcional)">
        <input id={`${prefijo}-direccion`} value={nuevo.direccion} onChange={(e) => cambiar({ ...nuevo, direccion: e.target.value })} className={claseInput} />
      </Campo>
      <label className="flex items-center gap-2 text-[15px]">
        <input type="checkbox" checked={nuevo.usaTicket} onChange={(e) => cambiar({ ...nuevo, usaTicket: e.target.checked })} className="size-4 accent-[var(--primary-color)]" />
        Da ticket
      </label>
    </>
  );
}

/** Cuenta nueva en la nube: crear el primer comercio (después se agregan más en Mis comercios o desde el ingreso). */
function PrimerComercio() {
  const crearComercio = useDatos((s) => s.crearComercio);
  const [nuevo, setNuevo] = useState<ComercioNuevo>(COMERCIO_VACIO);
  const [enviando, setEnviando] = useState(false);
  const [error, setError] = useState("");

  return (
    <form
      onSubmit={async (e) => {
        e.preventDefault();
        if (!nuevo.nombre.trim()) return setError("Escribí el nombre del comercio.");
        setError("");
        setEnviando(true);
        try {
          await crearComercio({ ...nuevo, nombre: nuevo.nombre.trim(), direccion: nuevo.direccion.trim() });
        } catch (err) {
          setError((err as Error).message);
        } finally {
          setEnviando(false);
        }
      }}
      className="flex flex-col gap-5 rounded-xl border border-borde bg-superficie p-6 shadow-sm shadow-black/[0.03] sm:p-8"
    >
      <div>
        <h1 className="text-xl font-semibold tracking-tight">¡Bienvenido a Mantenete!</h1>
        <p className="mt-1 text-sm text-texto-suave">Para empezar, cargá tu comercio. Si tenés más sucursales, las agregás después en Mis comercios (son gratis).</p>
      </div>
      <CamposComercio nuevo={nuevo} cambiar={setNuevo} prefijo="primer" />
      {error && <p className="text-sm text-peligro">{error}</p>}
      <Boton type="submit" variante="primario" icono={Store} disabled={enviando} className="h-11">
        {enviando ? "Creando…" : "Crear mi comercio"}
      </Boton>
    </form>
  );
}

